fn fibonacci(n: usize) -> Vec<i32> {
    // Handle the base cases for n = 0, 1, and 2 explicitly
    match n {
        0 => return vec![],
        1 => return vec![0],
        2 => return vec![0, 1],
        _ => {}
    }
    
    // For n >= 3, initialize with first two Fibonacci numbers
    let mut result = vec![0, 1];
    
    // Generate the remaining Fibonacci numbers
    for i in 2..n {
        let next = result[i - 1] + result[i - 2];
        result.push(next);
    }
    
    result
}